    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem),
  ro_cells asegs m A [C8 (Z_to_bv 64 beg); C8 w1; C8 (Z_to_bv 64 srz); C8 w3; C8 w4; C8 w5; C8 w6; C8 w7] ->
  rw_cells asegs m 0x11aa58 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x1195dc [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x117590 [C4 (Z_to_bv 64 1)] ->
  ro_cells asegs m 0x119d78 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x1ab920 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x10ca40 [C8 (Z_to_bv 64 0x1012a0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  ((XS1_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS1_HI)
   \/ (XS2_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS2_HI)
   \/ (XS3_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS3_HI)) ->
  0 <= beg -> beg mod 8 = 0 -> 8 <= srz -> srz mod 8 = 0 -> beg + srz <= 0x66f000 -> srz / 8 < 0x10000 ->
  0x10f580 <= A -> A + 64 <= 0x1166c0 -> 1 <= K <= 453 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
        ms' = MS (mkR (Z_to_bv 64 0x54678) sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x1ab8a8) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
                      (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 K)
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 0x54678) fc None m' (seg_rom asegs)
        /\ munch [(XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ stk asegs m' XS1_LO XS1_HI /\ stk asegs m' XS2_LO XS2_HI /\ stk asegs m' XS3_LO XS3_HI)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x1ab8a8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
             (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0x54690) fc None m (seg_rom asegs)).
Proof.
