Lemma unreg_iter_tail : forall (A K odr : Z) (w0 w1 w2 w3 w4 w5 w6 : word)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 : byte),
  ro_cells asegs m A [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 (Z_to_bv 64 odr)] ->
  rw_cells asegs m 0x64c402 [C1 o1] -> rw_cells asegs m 0x64c400 [C1 o2] -> rw_cells asegs m 0x64c401 [C1 o3] -> rw_cells asegs m 0x64c403 [C1 o4] ->
  (odr = ODR_NONE \/ odr = 0x64c402 \/ odr = 0x64c400 \/ odr = 0x64c401 \/ odr = 0x64c403) ->
  0x10f580 <= A -> A + 64 <= 0x1166c0 -> 1 <= K <= 453 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' : byte),
        ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x1ab8a8) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 (A + 64)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
                      (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 (K - 1))
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 (if K =? 1 then 0x54894 else 0x54690)) fc None m' (seg_rom asegs)
        /\ munch [(0x64c402, 0x64c404); (0x64c400, 0x64c402)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ rw_cells asegs m' 0x64c402 [C1 o1'] /\ rw_cells asegs m' 0x64c400 [C1 o2'] /\ rw_cells asegs m' 0x64c401 [C1 o3'] /\ rw_cells asegs m' 0x64c403 [C1 o4'])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x1ab8a8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x1d636) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x1175f0)
             (Z_to_bv 64 0x10ca40) (Z_to_bv 64 0x117630) (Z_to_bv 64 0x117578) (Z_to_bv 64 0x119d78) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0x54678) fc None m (seg_rom asegs)).
Proof.
